/**
 * Loads src/data/asisten.json (generated by scripts/seed_asisten.py from
 * the handbook) into the `asisten` table.
 *
 * Idempotent: an upsert keyed on `nim`, safe to re-run after every
 * regeneration of asisten.json rather than needing a separate
 * "has this already been seeded" check. Run after migrations:
 *
 *   python ../scripts/seed_asisten.py   (from web/, or run from repo root)
 *   npx tsx scripts/seed-db.ts
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { getDb } from "../src/lib/db";
import { asisten } from "../src/lib/schema";

const HERE = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(HERE, "..", "src", "data", "asisten.json");

interface AsistenRow {
  nim: string;
  nama: string;
  kode: string;
  divisiId: string;
  divisiEn: string;
}

async function main() {
  const raw = readFileSync(DATA_PATH, "utf-8");
  const rows: AsistenRow[] = JSON.parse(raw);

  if (rows.length === 0) {
    throw new Error(`${DATA_PATH} parsed to zero rows -- refusing to seed with nothing`);
  }

  const db = getDb();

  for (const row of rows) {
    await db
      .insert(asisten)
      .values(row)
      .onConflictDoUpdate({
        target: asisten.nim,
        set: {
          nama: row.nama,
          kode: row.kode,
          divisiId: row.divisiId,
          divisiEn: row.divisiEn,
        },
      });
  }

  console.log(`Seeded ${rows.length} assistants.`);
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
